# DK FVB.  Fårup - Viborg
#
let fv = path("d3.dk.fvb");

with detail = 4, railway = :first :removed {
    # point.dk.Fårup  dk.FFH

    with link = "line.dk.FVB" {
        track(:ror :casing,
                fv[:far.yv - 0.1dl, :far.yv] << 1.5mo
            ..  fv[:far.yv + 200m, :far.yv + 201m] << 2mo
            ..  fv[:far.zv, :far.zv + 0.1dl]
        );
        track(fv[:far.zv, :far.zv + 1.01km]);
        line_label(:right:e, fv[:far.zv + 1km] >> 0.5mt, "FVB");
        track(fv[:far.zv + 0.99km, :rej - 0.49sw]);
    }

    with link = "point.dk.Rejstrupgård", railway = :station {
        track(fv[:rej - 0.5sw, :rej + 0.5sw]);
        marker(:left :de.hp, fv[:rej] << 0.5mt);
        station(:right, fv[:rej] << 0.5mt << 1sh + (1.5dt, 1.5dt),
            "Rejstrupgård", "FVB: 3,8"
        );
    }

    with link = "line.dk.FVB" {
        track(fv[:rej + 0.49sw, :son - 0.49sw]);
    }

